// Raw history, written by hand from the shapes that shipped at each version. These objects must
// not be built from the current zod schemas: they model what old workspaces already contain.
export interface RawHistoricalEvent {
  id: 0;
  version: number;
  kind: string;
  entityId: string;
  actor: string;
  message: string;
  createdAt: string;
  data: Record<string, unknown>;
}

const at = (minute: number) => new Date(Date.UTC(2026, 8, 1, 9, minute)).toISOString();
const event = (
  version: number,
  kind: string,
  actor: string,
  message: string,
  minute: number,
  data: Record<string, unknown> & { id: string },
): RawHistoricalEvent => ({
  id: 0,
  version,
  kind,
  entityId: data.id,
  actor,
  message,
  createdAt: at(minute),
  data,
});

const role = (id: string, name: string, description: string, capabilities?: object) => ({
  id,
  name,
  description,
  runtime: 'demo',
  model: '',
  enabled: true,
  instructions: `${name} follows the shared job-search rules.`,
  ...(capabilities ? { capabilities } : {}),
});
const card = (
  id: string,
  company: string,
  state: string,
  owner: string | null,
  packet: object | null,
) => ({
  id,
  company,
  title: 'Platform Engineer',
  location: 'Remote',
  url: '',
  salary: '',
  description: `${company} is hiring a platform engineer.`,
  tags: ['legacy'],
  state,
  fit: state === 'lead' ? null : 82,
  owner,
  packet,
  feedback: [],
  createdAt: at(10),
  updatedAt: at(12),
  sample: false,
});
const packet = {
  resume: '# Pat Example\n\nBuilt internal tooling at Fictional Works.',
  coverLetter: 'Dear team,\n\nI would like to join Northwind Test.',
  formAnswers: '',
  note: 'Ready for approval.',
  claims: [
    {
      claim: 'Built internal tooling',
      source: 'work-history.md',
      quote: 'Built internal tooling at Fictional Works.',
    },
  ],
};

